from pydantic import BaseModel, validator
class AadhaarInput(BaseModel):
    number: str
    @validator('number')
    def must_be_12_digits(cls, v):
        if not v.isdigit() or len(v) != 12:
            raise ValueError('Invalid Aadhaar')
        return v

